      backup_text =
        "#Spectral Seed Catalog#\n\
         #A ghost gardener's seed catalog using untested HTML elements and \
         attributes#\n\
         #Exercises: Select, Option, OnChange, OnMouseEnter, OnMouseLeave, \
         OnDoubleClick,#\n\
         #Delay, CopyToClipboard, SubBatch, OnResize, Ol, H3, Hr, A, Href, \
         Classes, Checked#\n\n\
         type Msg =\n\
        \  + SelectCategory(String)\n\
        \  + HoverSeed(Int)\n\
        \  + UnhoverSeed\n\
        \  + CollectSeed(Int)\n\
        \  + DismissNotification\n\
        \  + ShareCollection\n\
        \  + WindowResized(Int, Int)\n\
        \  + ToggleNightMode\n\
         in\n\n\
         let seeds = [\n\
        \  (name=\"Phantom Orchid\", category=\"Flowers\", emoji=\"*\", \
         desc=\"Blooms only at midnight\"),\n\
        \  (name=\"Wraith Basil\", category=\"Herbs\", emoji=\"~\", \
         desc=\"Season your spectral soups\"),\n\
        \  (name=\"Ghost Cap\", category=\"Mushrooms\", emoji=\"^\", \
         desc=\"Glows with eerie light\"),\n\
        \  (name=\"Banshee Rose\", category=\"Flowers\", emoji=\"@\", \
         desc=\"Its thorns wail in wind\"),\n\
        \  (name=\"Spirit Sage\", category=\"Herbs\", emoji=\"&\", \
         desc=\"Grants visions of beyond\"),\n\
        \  (name=\"Shade Truffle\", category=\"Mushrooms\", emoji=\"#\", \
         desc=\"Found in haunted groves\")\n\
         ] in\n\n\
         let empty_ints : [Int] = [] in\n\
         let init = (\n\
        \  category=\"All\",\n\
        \  hoveredSeed= -1,\n\
        \  collected=empty_ints,\n\
        \  notification=\"\",\n\
        \  windowWidth=800,\n\
        \  nightMode=true\n\
         ) in\n\n\
         let contains(lst, val) =\n\
        \  length(filter(lst, fun x -> x == val)) > 0\n\
         in\n\n\
         let update(msg, model) =\n\
        \  case msg\n\
        \  | SelectCategory(cat) =>\n\
        \      ((category=cat, hoveredSeed=model.hoveredSeed, \
         collected=model.collected,\n\
        \        notification=model.notification, \
         windowWidth=model.windowWidth, nightMode=model.nightMode),\n\
        \       CmdNone)\n\
        \  | HoverSeed(idx) =>\n\
        \      ((category=model.category, hoveredSeed=idx, \
         collected=model.collected,\n\
        \        notification=model.notification, \
         windowWidth=model.windowWidth, nightMode=model.nightMode),\n\
        \       CmdNone)\n\
        \  | UnhoverSeed =>\n\
        \      ((category=model.category, hoveredSeed= -1, \
         collected=model.collected,\n\
        \        notification=model.notification, \
         windowWidth=model.windowWidth, nightMode=model.nightMode),\n\
        \       CmdNone)\n\
        \  | CollectSeed(idx) =>\n\
        \      if contains(model.collected, idx) then\n\
        \        (model, CmdNone)\n\
        \      else\n\
        \        let new_collected = model.collected @ [idx] in\n\
        \        ((category=model.category, hoveredSeed=model.hoveredSeed, \
         collected=new_collected,\n\
        \          notification=\"Seed collected!\", \
         windowWidth=model.windowWidth, nightMode=model.nightMode),\n\
        \         Delay(2000.0, DismissNotification))\n\
        \  | DismissNotification =>\n\
        \      ((category=model.category, hoveredSeed=model.hoveredSeed, \
         collected=model.collected,\n\
        \        notification=\"\", windowWidth=model.windowWidth, \
         nightMode=model.nightMode),\n\
        \       CmdNone)\n\
        \  | ShareCollection =>\n\
        \      let count_str = string_of_int(length(model.collected)) in\n\
        \      let text = \"My ghost garden has \" ++ count_str ++ \" spectral \
         seeds!\" in\n\
        \      ((category=model.category, hoveredSeed=model.hoveredSeed, \
         collected=model.collected,\n\
        \        notification=\"Copied to clipboard!\", \
         windowWidth=model.windowWidth, nightMode=model.nightMode),\n\
        \       CmdBatch([CopyToClipboard(text), Delay(2000.0, \
         DismissNotification)]))\n\
        \  | WindowResized(w, _h) =>\n\
        \      ((category=model.category, hoveredSeed=model.hoveredSeed, \
         collected=model.collected,\n\
        \        notification=model.notification, windowWidth=w, \
         nightMode=model.nightMode),\n\
        \       CmdNone)\n\
        \  | ToggleNightMode =>\n\
        \      ((category=model.category, hoveredSeed=model.hoveredSeed, \
         collected=model.collected,\n\
        \        notification=model.notification, windowWidth=model.windowWidth,\n\
        \        nightMode=if model.nightMode then false else true),\n\
        \       CmdNone)\n\
        \  end\n\
         in\n\n\
         let filtered_seeds(model) =\n\
        \  if model.category == \"All\" then seeds\n\
        \  else filter(seeds, fun s -> s.category == model.category)\n\
         in\n\n\
         let view(model) =\n\
        \  let bg = if model.nightMode then \"#1a1a2e\" else \"#f0e6d3\" in\n\
        \  let fg = if model.nightMode then \"#e0d0ff\" else \"#2d2d2d\" in\n\
        \  let accent = if model.nightMode then \"#7b2d8b\" else \"#8b4513\" in\n\
        \  let card_bg = if model.nightMode then \"#16213e\" else \"#fff8f0\" in\n\
        \  let is_wide = model.windowWidth > 600 in\n\
        \  Div(\n\
        \    [\n\
        \      Id(\"seed-catalog\"),\n\
        \      Classes([\"catalog-app\", if model.nightMode then \
         \"night-mode\" else \"day-mode\"]),\n\
        \      Style([\n\
        \        (\"max-width\", \"700px\"),\n\
        \        (\"margin\", \"20px auto\"),\n\
        \        (\"padding\", \"20px\"),\n\
        \        (\"font-family\", \"Georgia, serif\"),\n\
        \        (\"background\", bg),\n\
        \        (\"color\", fg),\n\
        \        (\"border-radius\", \"12px\"),\n\
        \        (\"border\", \"2px solid \" ++ accent)\n\
        \      ])\n\
        \    ],\n\
        \    [\n\
        \      #Title#\n\
        \      H1(\n\
        \        [Style([(\"text-align\", \"center\"), (\"letter-spacing\", \
         \"2px\"), (\"margin-bottom\", \"5px\")])],\n\
        \        [Text(\"Spectral Seed Catalog\")]\n\
        \      ),\n\
        \      P(\n\
        \        [Style([(\"text-align\", \"center\"), (\"font-style\", \
         \"italic\"), (\"margin-top\", \"0\")])],\n\
        \        [Text(\"A Late Night Ghost Gardener's Companion\")]\n\
        \      ),\n\n\
        \      #Night mode toggle with Checked#\n\
        \      Div(\n\
        \        [Style([(\"text-align\", \"right\"), (\"margin-bottom\", \
         \"10px\")])],\n\
        \        [\n\
        \          Label([], [\n\
        \            Input([\n\
        \              Type(\"checkbox\"),\n\
        \              Checked(model.nightMode),\n\
        \              OnClick(ToggleNightMode)\n\
        \            ]),\n\
        \            Text(\" Night Mode\")\n\
        \          ])\n\
        \        ]\n\
        \      ),\n\n\
        \      Hr([Style([(\"border-color\", accent), (\"margin\", \"15px \
         0\")])]),\n\n\
        \      #Decorative link#\n\
        \      A(\n\
        \        [Href(\"#ghostly-gardens\"), Style([(\"color\", accent), \
         (\"text-decoration\", \"none\")])],\n\
        \        [Text(\"Visit the Ghostly Gardens Archives\")]\n\
        \      ),\n\n\
        \      Hr([Style([(\"border-color\", accent), (\"margin\", \"15px \
         0\")])]),\n\n\
        \      #Category filter with Select and OnChange#\n\
        \      H3(\n\
        \        [Style([(\"margin-bottom\", \"8px\")])],\n\
        \        [Text(\"Filter by Category\")]\n\
        \      ),\n\
        \      Select(\n\
        \        [\n\
        \          OnChange(fun value -> SelectCategory(value)),\n\
        \          Style([\n\
        \            (\"padding\", \"8px 12px\"),\n\
        \            (\"font-size\", \"16px\"),\n\
        \            (\"border-radius\", \"6px\"),\n\
        \            (\"border\", \"1px solid \" ++ accent),\n\
        \            (\"background\", card_bg),\n\
        \            (\"color\", fg),\n\
        \            (\"margin-bottom\", \"15px\")\n\
        \          ])\n\
        \        ],\n\
        \        [\n\
        \          Option([Value(\"All\"), Selected(model.category == \
         \"All\")], \"All Seeds\"),\n\
        \          Option([Value(\"Flowers\"), Selected(model.category == \
         \"Flowers\")], \"Flowers\"),\n\
        \          Option([Value(\"Herbs\"), Selected(model.category == \
         \"Herbs\")], \"Herbs\"),\n\
        \          Option([Value(\"Mushrooms\"), Selected(model.category == \
         \"Mushrooms\")], \"Mushrooms\")\n\
        \        ]\n\
        \      ),\n\n\
        \      #Notification banner#\n\
        \      if model.notification != \"\" then\n\
        \        Div(\n\
        \          [Style([\n\
        \            (\"background\", \"#4a2c6a\"),\n\
        \            (\"color\", \"#e0d0ff\"),\n\
        \            (\"padding\", \"10px\"),\n\
        \            (\"border-radius\", \"6px\"),\n\
        \            (\"margin-bottom\", \"15px\"),\n\
        \            (\"text-align\", \"center\")\n\
        \          ])],\n\
        \          [Text(model.notification)]\n\
        \        )\n\
        \      else Div([], []),\n\n\
        \      #Seed cards with OnMouseEnter, OnMouseLeave, OnDoubleClick#\n\
        \      H3(\n\
        \        [Style([(\"margin-bottom\", \"8px\")])],\n\
        \        [Text(\"Seeds (\" ++ \
         string_of_int(length(filtered_seeds(model))) ++ \")\")]\n\
        \      ),\n\
        \      Div(\n\
        \        [Style([\n\
        \          (\"display\", if is_wide then \"grid\" else \"block\"),\n\
        \          (\"grid-template-columns\", \"1fr 1fr\"),\n\
        \          (\"gap\", \"10px\")\n\
        \        ])],\n\
        \        mapi(seeds, (fun (idx, seed) ->\n\
        \          if model.category == \"All\" || seed.category == \
         model.category then\n\
        \            Div(\n\
        \              [\n\
        \                Classes([\"seed-card\", seed.category]),\n\
        \                OnMouseEnter(HoverSeed(idx)),\n\
        \                OnMouseLeave(UnhoverSeed),\n\
        \                OnDoubleClick(CollectSeed(idx)),\n\
        \                Style([\n\
        \                  (\"padding\", \"12px\"),\n\
        \                  (\"border\", if contains(model.collected, idx) then \
         \"2px solid gold\" else \"1px solid \" ++ accent),\n\
        \                  (\"border-radius\", \"8px\"),\n\
        \                  (\"background\", if model.hoveredSeed == idx then \
         accent else card_bg),\n\
        \                  (\"cursor\", \"pointer\"),\n\
        \                  (\"transition\", \"background 0.2s\"),\n\
        \                  (\"margin-bottom\", if is_wide then \"0\" else \
         \"10px\")\n\
        \                ])\n\
        \              ],\n\
        \              [\n\
        \                Div(\n\
        \                  [Style([(\"display\", \"flex\"), \
         (\"justify-content\", \"space-between\"), (\"align-items\", \
         \"center\")])],\n\
        \                  [\n\
        \                    Span(\n\
        \                      [Style([(\"font-weight\", \"bold\"), \
         (\"font-size\", \"16px\")])],\n\
        \                      [Text(seed.emoji ++ \" \" ++ seed.name)]\n\
        \                    ),\n\
        \                    Span(\n\
        \                      [Style([(\"font-size\", \"12px\"), \
         (\"opacity\", \"0.7\")])],\n\
        \                      [Text(seed.category)]\n\
        \                    )\n\
        \                  ]\n\
        \                ),\n\
        \                if model.hoveredSeed == idx then\n\
        \                  P(\n\
        \                    [Style([(\"margin\", \"8px 0 0 0\"), \
         (\"font-style\", \"italic\"), (\"font-size\", \"14px\")])],\n\
        \                    [Text(seed.desc)]\n\
        \                  )\n\
        \                else Div([], []),\n\
        \                if contains(model.collected, idx) then\n\
        \                  Span(\n\
        \                    [Style([(\"font-size\", \"11px\"), (\"color\", \
         \"gold\")])],\n\
        \                    [Text(\"Collected\")]\n\
        \                  )\n\
        \                else\n\
        \                  Span(\n\
        \                    [Style([(\"font-size\", \"11px\"), (\"opacity\", \
         \"0.5\")])],\n\
        \                    [Text(\"Double-click to collect\")]\n\
        \                  )\n\
        \              ]\n\
        \            )\n\
        \          else Div([Style([(\"display\", \"none\")])], [])\n\
        \        ))\n\
        \      ),\n\n\
        \      Hr([Style([(\"border-color\", accent), (\"margin\", \"20px \
         0\")])]),\n\n\
        \      #Collected seeds with Ol#\n\
        \      H3(\n\
        \        [Style([(\"margin-bottom\", \"8px\")])],\n\
        \        [Text(\"Your Collection (\" ++ \
         string_of_int(length(model.collected)) ++ \")\")]\n\
        \      ),\n\
        \      if length(model.collected) > 0 then\n\
        \        Div([], [\n\
        \          Ol(\n\
        \            [Style([(\"padding-left\", \"20px\")])],\n\
        \            map(model.collected, fun idx ->\n\
        \              Li(\n\
        \                [Style([(\"margin-bottom\", \"4px\")])],\n\
        \                [Text(nth(seeds, idx).name)]\n\
        \              )\n\
        \            )\n\
        \          ),\n\
        \          #Share button with CopyToClipboard#\n\
        \          Button(\n\
        \            [\n\
        \              OnClick(ShareCollection),\n\
        \              Classes([\"share-btn\"]),\n\
        \              Style([\n\
        \                (\"margin-top\", \"10px\"),\n\
        \                (\"padding\", \"8px 16px\"),\n\
        \                (\"background\", accent),\n\
        \                (\"color\", \"white\"),\n\
        \                (\"border\", \"none\"),\n\
        \                (\"border-radius\", \"6px\"),\n\
        \                (\"cursor\", \"pointer\"),\n\
        \                (\"font-size\", \"14px\")\n\
        \              ])\n\
        \            ],\n\
        \            [Text(\"Share Collection\")]\n\
        \          )\n\
        \        ])\n\
        \      else\n\
        \        P(\n\
        \          [Style([(\"font-style\", \"italic\"), (\"opacity\", \
         \"0.6\")])],\n\
        \          [Text(\"No seeds collected yet. Double-click a seed to add \
         it!\")]\n\
        \        ),\n\n\
        \      Hr([Style([(\"border-color\", accent), (\"margin\", \"20px \
         0\")])]),\n\n\
        \      #Footer with window width display#\n\
        \      Div(\n\
        \        [Style([(\"text-align\", \"center\"), (\"font-size\", \
         \"12px\"), (\"opacity\", \"0.5\")])],\n\
        \        [Text(\"Window width: \" ++ string_of_int(model.windowWidth) \
         ++ \"px\")]\n\
        \      )\n\
        \    ]\n\
        \  )\n\
         in\n\n\
         let subs(_model) =\n\
        \  SubBatch([\n\
        \    OnResize(fun (w, h) -> WindowResized(w, h))\n\
        \  ])\n\
         in\n\n\
         # Tests #\n\n\
         hint \"select category filters to Flowers\"\n\
         test\n\
        \  let (m, _cmd) = update(SelectCategory(\"Flowers\"), init) in\n\
        \  m.category == \"Flowers\"\n\
         end;\n\n\
         hint \"select All shows all categories\"\n\
         test\n\
        \  let (m, _cmd) = update(SelectCategory(\"All\"), init) in\n\
        \  m.category == \"All\"\n\
         end;\n\n\
         hint \"hover seed sets hoveredSeed\"\n\
         test\n\
        \  let (m, _cmd) = update(HoverSeed(2), init) in\n\
        \  m.hoveredSeed == 2\n\
         end;\n\n\
         hint \"unhover resets hoveredSeed\"\n\
         test\n\
        \  let hovered = (category=\"All\", hoveredSeed=3, \
         collected=empty_ints, notification=\"\", windowWidth=800, \
         nightMode=true) in\n\
        \  let (m, _cmd) = update(UnhoverSeed, hovered) in\n\
        \  m.hoveredSeed == -1\n\
         end;\n\n\
         hint \"collect seed adds to collection\"\n\
         test\n\
        \  let (m, _cmd) = update(CollectSeed(0), init) in\n\
        \  m.collected == [0] && m.notification == \"Seed collected!\"\n\
         end;\n\n\
         hint \"collect duplicate does not add\"\n\
         test\n\
        \  let with_one = (category=\"All\", hoveredSeed= -1, collected=[0], \
         notification=\"\", windowWidth=800, nightMode=true) in\n\
        \  let (m, _cmd) = update(CollectSeed(0), with_one) in\n\
        \  m.collected == [0]\n\
         end;\n\n\
         hint \"dismiss notification clears message\"\n\
         test\n\
        \  let with_notif = (category=\"All\", hoveredSeed= -1, \
         collected=empty_ints, notification=\"hello\", windowWidth=800, \
         nightMode=true) in\n\
        \  let (m, _cmd) = update(DismissNotification, with_notif) in\n\
        \  m.notification == \"\"\n\
         end;\n\n\
         hint \"window resize updates width\"\n\
         test\n\
        \  let (m, _cmd) = update(WindowResized(1024, 768), init) in\n\
        \  m.windowWidth == 1024\n\
         end;\n\n\
         hint \"share collection sets notification\"\n\
         test\n\
        \  let (m, _cmd) = update(ShareCollection, init) in\n\
        \  m.notification == \"Copied to clipboard!\"\n\
         end;\n\n\
         hint \"toggle night mode off\"\n\
         test\n\
        \  let (m, _cmd) = update(ToggleNightMode, init) in\n\
        \  m.nightMode == false\n\
         end;\n\n\
         hint \"toggle night mode on again\"\n\
         test\n\
        \  let day = (category=\"All\", hoveredSeed= -1, collected=empty_ints, \
         notification=\"\", windowWidth=800, nightMode=false) in\n\
        \  let (m, _cmd) = update(ToggleNightMode, day) in\n\
        \  m.nightMode == true\n\
         end;\n\n\
         hint \"collect multiple seeds\"\n\
         test\n\
        \  let (m1, _c1) = update(CollectSeed(1), init) in\n\
        \  let (m2, _c2) = update(CollectSeed(4), m1) in\n\
        \  m2.collected == [1, 4]\n\
         end;\n\n\
         (init, update, view, subs)\n";
      refractors = "()";
    } )
